using System.Net;
using System.Text;
using System.Text.Json;
using GnazzosWorld.Core.Commerce;
using GnazzosWorld.Core.Fulfillment;
using GnazzosWorld.Core.Identity;
using GnazzosWorld.Core.Orders;
using GnazzosWorld.Core.Payments;
using Microsoft.Data.Sqlite;
using Xunit;

namespace GnazzosWorld.Core.Tests;

public sealed class FulfillmentTests:IDisposable
{
    private static CancellationToken Ct=>TestContext.Current.CancellationToken;
    private readonly string root=Path.Combine(Path.GetTempPath(),"gnazzo-fulfillment-"+Guid.NewGuid().ToString("N"));private string Server=>Path.Combine(root,"server.db");private string Client=>Path.Combine(root,"client.db");
    private readonly Clock clock=new();private static readonly OrderOwner A=new("https://fixture.auth0.com/","reader-a"),B=new("https://fixture.auth0.com/","reader-b");private static string Key()=>Guid.NewGuid().ToString("N");
    private static OrderSnapshot Accept(SqliteOrderStore s,OrderOwner? owner=null){var actor=owner??A;var q=s.CreateQuote(actor,new SongRequest{Genre="Folk",Occasion="Invented anniversary",Story="Synthetic story",ContactName="Sample Reader",Email="reader@example.test"});return s.Accept(actor,new(q.Id,Key(),q.Request));}
    private OrderSnapshot Ready(SqliteOrderStore s)
    {
        var o=Accept(s);var r=s.ReserveTestCheckout(A,o.Id,"stripe-test:acct_fixture","https://api.example.test/");s.AttachTestSession(r,new("cs_test_"+r.AttemptId,"https://checkout.stripe.com/c/"+r.AttemptId));var bytes=PaymentTests.Payload(r,"evt_"+r.AttemptId);
        var e=new StripeTestEventVerifier("whsec_synthetic_fixture_secret_0123456789",r.Scope,clock).Verify(bytes,PaymentTests.Sign(bytes,clock.Now.ToUnixTimeSeconds()))!;s.ApplyVerifiedTestEvent(e);s.StartProductionForPaymentLab(o.Id,1);return s.PublishReviewForLab(o.Id,2);
    }
    private CommerceAccount Account(OrderOwner? owner=null)=>new(owner??A,"https://api.example.test/","https://gnazzosworld.example/api");
    [Fact] public void Owned_live_keyset_pages_do_not_include_other_accounts()
    {using var s=new SqliteOrderStore(Server,clock);for(var i=0;i<23;i++)Accept(s);Accept(s,B);var first=s.ListOrders(A);Assert.Equal(20,first.Items.Count);var last=s.ListOrders(A,first.Next);Assert.Equal(3,last.Items.Count);Assert.Null(last.Next);Assert.Equal(23,first.Items.Concat(last.Items).Select(x=>x.Id).Distinct().Count());Assert.Single(s.ListOrders(B).Items);}
    [Fact] public void Tracking_is_one_owned_snapshot_with_ordered_history_and_notice()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var t=s.TrackOrder(A,ready.Id);Assert.Equal(ready,t.Order);Assert.Equal(new long[]{1,2,3},t.History.Select(h=>h.Version));Assert.Equal(OrderNoticeKind.ReadyForReview,Assert.Single(t.Notices).Kind);Assert.Throws<OrderRejectedException>(()=>s.TrackOrder(B,ready.Id));}
    [Fact] public void Revision_is_atomic_and_replays_before_later_version_checks()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var command=new RevisionCommand(ready.Version,Key(),"  Invented lyric adjustment  ");var receipt=s.RequestRevision(A,ready.Id,command);Assert.Equal("Invented lyric adjustment",receipt.Note);Assert.Equal(4,receipt.AppliedVersion);s.PublishReviewForLab(ready.Id,4);Assert.Equal(receipt,s.RequestRevision(A,ready.Id,command));var t=s.TrackOrder(A,ready.Id);Assert.Single(t.Revisions);Assert.Equal(5,t.Order.Version);Assert.Equal(3,t.Notices.Count);}
    [Theory][InlineData("version")][InlineData("note")]
    public void Reusing_revision_key_with_changed_facts_is_a_conflict(string changed)
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var c=new RevisionCommand(3,Key(),"Original synthetic note");s.RequestRevision(A,ready.Id,c);var bad=changed=="note"?c with{Note="Different"}:c with{ExpectedVersion=4};Assert.Equal(OrderProblem.KeyConflict,Assert.Throws<OrderRejectedException>(()=>s.RequestRevision(A,ready.Id,bad)).Problem);}
    [Fact] public void Stale_version_wrong_state_and_foreign_owner_cannot_revise()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);Assert.Equal(OrderProblem.VersionConflict,Assert.Throws<OrderRejectedException>(()=>s.RequestRevision(A,ready.Id,new(2,Key(),"Synthetic"))).Problem);Assert.Equal(OrderProblem.Unavailable,Assert.Throws<OrderRejectedException>(()=>s.RequestRevision(B,ready.Id,new(3,Key(),"Synthetic"))).Problem);s.RequestRevision(A,ready.Id,new(3,Key(),"First"));Assert.Equal(OrderProblem.InvalidTransition,Assert.Throws<OrderRejectedException>(()=>s.RequestRevision(A,ready.Id,new(4,Key(),"Second"))).Problem);}
    [Theory][InlineData("")][InlineData("\u0001")][InlineData(null)]
    public void Invalid_revision_notes_are_rejected(string? note)
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);Assert.Equal(OrderProblem.InvalidRequest,Assert.Throws<OrderRejectedException>(()=>s.RequestRevision(A,ready.Id,new(3,Key(),note!))).Problem);}
    [Fact] public void Oversized_note_and_revision_capacity_are_bounded()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);Assert.Throws<OrderRejectedException>(()=>s.RequestRevision(A,ready.Id,new(3,Key(),new string('x',1001))));var version=3L;for(var i=0;i<10;i++){s.RequestRevision(A,ready.Id,new(version,Key(),"Synthetic "+i));s.PublishReviewForLab(ready.Id,++version);version++;}Assert.Equal(OrderProblem.Capacity,Assert.Throws<OrderRejectedException>(()=>s.RequestRevision(A,ready.Id,new(version,Key(),"Eleventh"))).Problem);Assert.Equal(10,s.TrackOrder(A,ready.Id).Revisions.Count);}
    [Fact] public void Failure_in_notice_insert_rolls_back_revision_order_and_history()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);Sql(Server,"CREATE TRIGGER fail_notice BEFORE INSERT ON commerce_notices BEGIN SELECT RAISE(ABORT,'synthetic'); END");var c=new RevisionCommand(3,Key(),"Synthetic");Assert.Throws<SqliteException>(()=>s.RequestRevision(A,ready.Id,c));Assert.Equal(3,s.TrackOrder(A,ready.Id).Order.Version);Assert.Empty(s.TrackOrder(A,ready.Id).Revisions);Sql(Server,"DROP TRIGGER fail_notice");Assert.Equal(4,s.RequestRevision(A,ready.Id,c).AppliedVersion);}
    [Fact] public async Task Concurrent_revision_retries_create_one_receipt()
    {using var a=new SqliteOrderStore(Server,clock);using var b=new SqliteOrderStore(Server,clock);var ready=Ready(a);var c=new RevisionCommand(3,Key(),"Synthetic");var results=await Task.WhenAll(Task.Run(()=>a.RequestRevision(A,ready.Id,c),Ct),Task.Run(()=>b.RequestRevision(A,ready.Id,c),Ct));Assert.Equal(results[0],results[1]);Assert.Single(a.TrackOrder(A,ready.Id).Revisions);}
    [Fact] public void Delivery_publication_is_replay_safe_with_atomic_history_and_notice()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);Assert.Equal(d,s.PublishDeliveryForLab(ready.Id,3));var t=s.TrackOrder(A,ready.Id);Assert.Equal(OrderState.Delivered,t.Order.State);Assert.Equal(4,t.Order.Version);Assert.Single(t.Deliveries);Assert.Single(t.Notices.Where(n=>n.Kind==OrderNoticeKind.Delivered));}
    [Fact] public void Failed_delivery_notice_rolls_back_publication()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);Sql(Server,"CREATE TRIGGER fail_notice BEFORE INSERT ON commerce_notices BEGIN SELECT RAISE(ABORT,'synthetic'); END");Assert.Throws<SqliteException>(()=>s.PublishDeliveryForLab(ready.Id,3));Assert.Empty(s.TrackOrder(A,ready.Id).Deliveries);Assert.Equal(3,s.TrackOrder(A,ready.Id).Order.Version);}
    [Fact] public void Foreign_wrong_delivery_and_expired_grants_do_not_authorize()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);var grant=s.IssueDeliveryGrant(A,ready.Id,d.Id,4);Assert.Equal(d,s.AuthorizeDelivery(A,ready.Id,d.Id,grant.Token));Assert.Throws<OrderRejectedException>(()=>s.AuthorizeDelivery(B,ready.Id,d.Id,grant.Token));Assert.Throws<OrderRejectedException>(()=>s.AuthorizeDelivery(A,ready.Id,Key(),grant.Token));clock.Now=grant.ExpiresAt;Assert.Throws<OrderRejectedException>(()=>s.AuthorizeDelivery(A,ready.Id,d.Id,grant.Token));Assert.NotEqual(grant.Token,s.IssueDeliveryGrant(A,ready.Id,d.Id,4).Token);}
    [Fact] public void Grant_hash_is_stored_instead_of_raw_credential_and_reopen_preserves_access()
    {OrderSnapshot ready;DeliveryDescriptor d;DeliveryGrant g;using(var s=new SqliteOrderStore(Server,clock)){ready=Ready(s);d=s.PublishDeliveryForLab(ready.Id,3);g=s.IssueDeliveryGrant(A,ready.Id,d.Id,4);}using var reopened=new SqliteOrderStore(Server,clock);Assert.Equal(d,reopened.AuthorizeDelivery(A,ready.Id,d.Id,g.Token));using var db=new SqliteConnection("Data Source="+Server+";Pooling=False");db.Open();using var c=db.CreateCommand();c.CommandText="SELECT token_hash FROM commerce_delivery_grants";Assert.DoesNotContain(g.Token,(string)c.ExecuteScalar()!);Assert.DoesNotContain(g.Token,g.ToString());}
    [Fact] public void Grant_capacity_is_bounded_and_expiry_cleanup_reclaims_rows()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);for(var i=0;i<4;i++)s.IssueDeliveryGrant(A,ready.Id,d.Id,4);Assert.Equal(OrderProblem.Capacity,Assert.Throws<OrderRejectedException>(()=>s.IssueDeliveryGrant(A,ready.Id,d.Id,4)).Problem);clock.Now=clock.Now.AddMinutes(2);Assert.NotNull(s.IssueDeliveryGrant(A,ready.Id,d.Id,4));}
    [Fact] public void Revocation_invalidates_existing_grants_and_publication_replay_cannot_restore_it()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);var g=s.IssueDeliveryGrant(A,ready.Id,d.Id,4);s.RevokeDeliveryForLab(ready.Id,d.Id,4);Assert.Throws<OrderRejectedException>(()=>s.AuthorizeDelivery(A,ready.Id,d.Id,g.Token));Assert.Throws<OrderRejectedException>(()=>s.IssueDeliveryGrant(A,ready.Id,d.Id,5));Assert.True(s.PublishDeliveryForLab(ready.Id,3).Revoked);Assert.Equal(OrderNoticeKind.DeliveryRevoked,s.TrackOrder(A,ready.Id).Notices[^1].Kind);}
    [Fact] public void Stale_delivery_version_and_graph_only_unpaid_fixture_are_not_authority()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);Assert.Equal(OrderProblem.VersionConflict,Assert.Throws<OrderRejectedException>(()=>s.IssueDeliveryGrant(A,ready.Id,d.Id,3)).Problem);var unpaid=Accept(s);s.AdvanceForLab(unpaid.Id,1,OrderState.InProduction);Assert.Throws<OrderRejectedException>(()=>s.PublishReviewForLab(unpaid.Id,2));}
    [Fact] public void Revision_journal_survives_reopen_isolates_resources_and_blocks_unresolved_replacement()
    {var id=Key();PendingRevision saved;using(var p=new PendingRevisionDatabase(Client)){saved=p.Begin(Account(),id,3,"Synthetic");Assert.Throws<InvalidOperationException>(()=>p.Begin(Account(),id,3,"Other"));}using var reopened=new PendingRevisionDatabase(Client);Assert.Equal(saved,reopened.Read(Account(),id));Assert.Null(reopened.Read(Account(B),id));Assert.Null(reopened.Read(Account() with{Audience="https://other.example/api"},id));Assert.False(PendingRevisionDatabase.Definitive(OrderProblem.KeyConflict));Assert.False(PendingRevisionDatabase.Definitive(OrderProblem.InvalidRequest));}
    [Fact] public async Task Revision_persistence_failure_sends_no_HTTP()
    {using var journal=new PendingRevisionDatabase(Client);Sql(Client,"CREATE TRIGGER fail_save BEFORE INSERT ON pending_revisions BEGIN SELECT RAISE(ABORT,'synthetic'); END");var session=Session();var count=0;using var api=new TrackingApiClient(session,new Handler(_=>{count++;throw new InvalidOperationException();}),clock);var owner=await session.AcquireOwnedAsync(Ct);await Assert.ThrowsAsync<SqliteException>(()=>new RevisionCoordinator(api,journal).SubmitAsync(Key(),3,"Synthetic",owner,Ct));Assert.Equal(0,count);}
    [Fact] public async Task Lost_revision_reply_reopens_both_databases_and_replays_original_key_after_new_review()
    {
        string id,key;using(var s=new SqliteOrderStore(Server,clock))using(var j=new PendingRevisionDatabase(Client)){id=Ready(s).Id;var session=Session();using var api=new TrackingApiClient(session,new Handler(async request=>{var c=JsonSerializer.Deserialize<RevisionCommand>(await request.Content!.ReadAsStringAsync(Ct),OrderContract.Json)!;s.RequestRevision(A,id,c);throw new HttpRequestException("Synthetic lost committed reply");}),clock);var lease=await session.AcquireOwnedAsync(Ct);await Assert.ThrowsAsync<HttpRequestException>(()=>new RevisionCoordinator(api,j).SubmitAsync(id,3,"Synthetic lost reply",lease,Ct));key=j.Read(Account(),id)!.Command.OperationKey;s.PublishReviewForLab(id,4);}
        using var reopened=new SqliteOrderStore(Server,clock);using var journal=new PendingRevisionDatabase(Client);var again=Session();using var retry=new TrackingApiClient(again,new Handler(async request=>{var c=JsonSerializer.Deserialize<RevisionCommand>(await request.Content!.ReadAsStringAsync(Ct),OrderContract.Json)!;Assert.Equal(key,c.OperationKey);return Json(reopened.RequestRevision(A,id,c));}),clock);var receipt=await new RevisionCoordinator(retry,journal).ResumeAsync(id,await again.AcquireOwnedAsync(Ct),Ct);Assert.Equal(4,receipt.AppliedVersion);Assert.Single(reopened.TrackOrder(A,id).Revisions);Assert.Equal(5,reopened.TrackOrder(A,id).Order.Version);Assert.Equal(receipt,journal.Read(Account(),id)!.Confirmed);
    }
    [Fact] public async Task Sign_out_during_committed_revision_keeps_original_account_pending()
    {using var s=new SqliteOrderStore(Server,clock);using var j=new PendingRevisionDatabase(Client);var id=Ready(s).Id;var committed=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var session=Session();using var api=new TrackingApiClient(session,new Handler(async request=>{var c=JsonSerializer.Deserialize<RevisionCommand>(await request.Content!.ReadAsStringAsync(Ct),OrderContract.Json)!;var receipt=s.RequestRevision(A,id,c);committed.SetResult();await release.Task;return Json(receipt);}),clock);var task=new RevisionCoordinator(api,j).SubmitAsync(id,3,"Synthetic delayed",await session.AcquireOwnedAsync(Ct),Ct);await committed.Task;await session.SignOutLocalAsync();release.SetResult();await Assert.ThrowsAsync<SessionEndedException>(()=>task);Assert.Null(j.Read(Account(),id)!.Confirmed);Assert.Null(j.Read(Account(B),id));}
    [Fact] public async Task Private_client_verifies_sample_and_clears_owned_buffer_on_dispose()
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);var session=Session();var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","delivery_sample.wav"));using var api=new TrackingApiClient(session,new Handler(request=>Task.FromResult(request.Method==HttpMethod.Post?Json(s.IssueDeliveryGrant(A,ready.Id,d.Id,4)):Audio(s,ready.Id,d.Id,request,bytes))),clock);using var verified=await api.FetchAsync(ready.Id,d,4,await session.AcquireOwnedAsync(Ct),Ct);Assert.Equal("RIFF",Encoding.ASCII.GetString(verified.Bytes.Span[..4]));Assert.Equal(96044,verified.Bytes.Length);var memory=verified.Bytes;verified.Dispose();Assert.True(memory.Span.IndexOfAnyExcept((byte)0)<0);}
    [Theory][InlineData("hash")][InlineData("size")][InlineData("type")]
    public async Task Corrupt_oversized_or_wrong_media_delivery_is_rejected(string defect)
    {using var s=new SqliteOrderStore(Server,clock);var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);var session=Session();var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","delivery_sample.wav"));if(defect=="hash")bytes[44]^=1;if(defect=="size")bytes=bytes.Concat(new byte[]{0}).ToArray();using var api=new TrackingApiClient(session,new Handler(request=>{if(request.Method==HttpMethod.Post)return Task.FromResult(Json(s.IssueDeliveryGrant(A,ready.Id,d.Id,4)));var r=Audio(s,ready.Id,d.Id,request,bytes);if(defect=="type")r.Content.Headers.ContentType=new("text/html");return Task.FromResult(r);}),clock);var lease=await session.AcquireOwnedAsync(Ct);await Assert.ThrowsAsync<InvalidDataException>(()=>api.FetchAsync(ready.Id,d,4,lease,Ct));}
    private static HttpResponseMessage Audio(SqliteOrderStore s,string order,string delivery,HttpRequestMessage r,byte[] bytes){s.AuthorizeDelivery(A,order,delivery,Assert.Single(r.Headers.GetValues("X-Delivery-Grant")));Assert.Empty(r.RequestUri!.Query);return new(HttpStatusCode.OK){Content=new ByteArrayContent(bytes){Headers={ContentType=new("audio/wav")}}};}
    private static HttpResponseMessage Json(object value)=>new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(value,OrderContract.Json),Encoding.UTF8,"application/json")};
    private ApiSession Session()=>new(new(new("fixture.auth0.com","public-client-id"),"https://gnazzosworld.example/api",new("https://api.example.test/")),new Vault(new(new("https://fixture.auth0.com/"),"reader-a","https://gnazzosworld.example/api","synthetic-access",null,clock.Now.AddMinutes(20))),new Provider(),clock);
    private static void Sql(string path,string sql){using var db=new SqliteConnection("Data Source="+path+";Pooling=False");db.Open();using var c=db.CreateCommand();c.CommandText=sql;c.ExecuteNonQuery();}
    private sealed class Handler(Func<HttpRequestMessage,Task<HttpResponseMessage>> send):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct)=>send(r);}
    private sealed class Vault(SessionGrant initial):ISessionVault{private SessionGrant? value=initial;public Task<SessionGrant?> ReadAsync(CancellationToken ct)=>Task.FromResult(value);public Task WriteAsync(SessionGrant? v,CancellationToken ct){value=v;return Task.CompletedTask;}}
    private sealed class Provider:ISessionProvider{public Task<SessionGrant> SignInAsync(CancellationToken ct)=>throw new InvalidOperationException();public Task<SessionGrant> RefreshAsync(SessionGrant previous,CancellationToken ct)=>throw new InvalidOperationException();}
    private sealed class Clock:TimeProvider{public DateTimeOffset Now=new(2026,11,16,12,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>Now;}
    public void Dispose(){if(Directory.Exists(root))Directory.Delete(root,true);}
}
